// CreateNewProject.js
import React, { useEffect, useState, useContext } from "react";
import axios from "axios";
import { Table, Button, Modal, Form } from "react-bootstrap";
import { Link } from "react-router-dom";
import { useNavigate } from "react-router-dom";
import {
    HouseDoorFill,
    ListCheck,
    Calendar3,
    BarChart,
    People,
    Gear,
    QuestionCircle,
    BoxArrowRight,
    PersonCircle,
    Search,
    ArrowBarDown,
    ArrowBarUp,
    Plus,
    X,
    Download,
    Upload
} from "react-bootstrap-icons";
import { CheckSquare, ClipboardList, ListTodo, ShieldCheck } from "lucide-react";
import "bootstrap/dist/css/bootstrap.min.css";
import "../css/Table.css"
import SearchInputFields from "../components/SearchInputFields"
import Pager from "../components/Pager";
import { useOutletContext } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import LoadingSpinner from "../components/LoadingSpinner";
import "../css/ModuleDashboard.css"
import { OverlayTrigger, Tooltip } from "react-bootstrap";
import { FaSleigh } from "react-icons/fa";
import { TrainingContext } from "./TrainingContext";
const BASE_URL = process.env.REACT_APP_BASE_URL;



const StoreMaterialMaster = () => {
    const [loading, setLoading] = useState(true);
    const [tableData, setTableData] = useState([]);
    const [formData, setFormData] = useState({
        category:{
            category: ""
        },
        material: "",
        description: "",
        createdBy: "",
        dateTime: "",
        image: ""
    });
    const [error, setError] = useState("");
    const [currentPage, setCurrentPage] = useState(0);
    const [totalPages, setTotalPages] = useState(0);
    const [pageSize, setPageSize] = useState(10);// dynamic in real apps
    const sequenceNumber = pageSize * currentPage;
    const navigate = useNavigate();
    const [expandedRow, setExpandedRow] = useState(null);
    const { setAlert, setStaticAlert, setResourceList, setReloadFunction } = useOutletContext();

    const toggleRow = (groupId) => {
        setExpandedRow(expandedRow === groupId ? null : groupId);
    };

    // const handleChange = (e) => {
    //     const { name, value } = e.target;
    //     setFormData((prev) => ({
    //         ...prev,      // keep all existing keys
    //         [name]: value,
    //          // update only the changed field
    //     }));
    // };

    const handleChange = (e) => {
        const { name, value } = e.target;
        const keys = name.split(".");

        setFormData(prev => {
            const updated = { ...prev };
            let current = updated;

            keys.forEach((key, index) => {
                if (index === keys.length - 1) {
                    current[key] = value;
                } else {
                    current[key] = { ...current[key] };
                    current = current[key];
                }
            });

            return updated;
        });
    };


    // Handle form change
    const loadTableData = async () => {
        try {
            console.log(formData);
            setLoading(true);
            const response = await axios.post(
                BASE_URL + "/WebApplication/Controllers/getLikestoreMaterial/" + currentPage + "/" + pageSize,
                formData,
                { withCredentials: true, } // 🚨 This ensures browser stores cookie 
            );
            console.log("Data Load Successfully:", response);
            // Redirect to dashboard
            setTableData(response.data.content);
            setTotalPages(response.data.totalPages);
            setCurrentPage(response.data.pageable.pageNumber);
            setLoading(false);
        } catch (error) {
            console.log(error);
            setLoading(false);
        }

    };

    // useEffect(() => {
    //     if (setReloadFunction) {
    //         setReloadFunction(() => loadTableData);
    //     }
    // }, []);

    // Handle form change
    const deleteData = async (formData) => {
        try {
            const response = await axios.post(
                BASE_URL + "/WebApplication/Controllers/deletePlantMaster",
                formData,
                { withCredentials: true, } // 🚨 This ensures browser stores cookie 
            );

            setAlert({ type: "success", message: "Success : " + response.data });
            loadTableData();
        } catch (error) {
            setAlert({ type: "danger", message: "Error : " + error.response.data });
            console.error(error);
            loadTableData();
        }
    };

    useEffect(() => {
        loadTableData();
    }, [currentPage, pageSize]); // empty deps → runs once

    const handleEnterKey = (e, callback) => {
        if (e.key === "Enter") {
            e.preventDefault();
            callback();
        }
    };

    const downloadTemplate = async () => {
        try {

            setLoading(true);

            const response = await axios.get(
                BASE_URL + "/WebApplication/Controllers/download/template/plantmaster",
                {
                    responseType: "blob", // ✅ VERY IMPORTANT
                    withCredentials: true,
                }
            );

            // Create blob link
            const url = window.URL.createObjectURL(new Blob([response.data]));

            const link = document.createElement("a");
            link.href = url;
            link.setAttribute("download", "location_Master_Template.xlsx");
            document.body.appendChild(link);
            link.click();

            // Cleanup
            link.remove();
            window.URL.revokeObjectURL(url);

            setLoading(false);

        } catch (error) {
            console.error("Download error:", error);

            setLoading(false);
        }
    };

    // Resource mode
    const showUploadModal = async (resources) => {
        setStaticAlert({ type: "success", message: "Resource Download : " });
        // setUploadUrl("uploadplant");

    };

    return (
        <div className="card shadow-lg rounded-0 border-0 bg-light d-flex flex-column p-2"
            style={{
                width: "100%",
                minHeight: "100vh",
                background: "#f4f6f8",
            }}>
            {/* Header */}
            <div className="px-4 py-2"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>
                {/* Title */}
                <h4 className="text-end fw-bold mb-0"><ClipboardList size={30} viewBox="0 1 24 24" className="me-2 text-white" />
                    Store Material Master</h4>
            </div>

            <div className="row g-4 px-1">
                {/* Left Side - Form */}
                <div className="col-md-12">
                    <div className="d-flex my-1" style={{ height: "80vh" }}>
                        {/* LEFT SIDE TABLE */}
                        <div style={{ flex: 1, overflowY: "auto" }}>

                            {loading ? (
                                <LoadingSpinner message={`Loading .....`} />
                            ) : (
                        <Table
                            bordered
                            hover
                            responsive
                            className="align-middle shadow-sm rounded custom-table responsive-table"
                        // className="table align-middle table-hover mb-0"
                        >
                            <thead className="bg-light sticky-top">
                                <tr>
                                    <th colSpan={2}>
                                        <Button
                                            variant="outline-success"
                                            size="sm"
                                            className="me-2 btn-woco"
                                        >
                                            <Search className="me-1" /> Search
                                        </Button>
                                    </th>
                                    <th><SearchInputFields type="text" placeholder="Location Name" name="plantName" onChange={(e) => handleChange(e)} value={formData?.plantName} onKeyDown={(e) => handleEnterKey(e, loadTableData)} /></th>
                                    <th><SearchInputFields type="text" placeholder="Bin Name" name="plantCode" onChange={(e) => handleChange(e)} value={formData?.plantCode} onKeyDown={(e) => handleEnterKey(e, loadTableData)} /></th>

                                </tr>
                            </thead>

                            <thead style={{ backgroundColor: "#0f6b5b", color: "#fff" }}>
                                <tr>
                                    <th>Edit / Delete</th>
                                    <th>S.No</th>
                                    <th>Material</th>
                                    <th>Category</th>
                                    <th>Description</th>
                                    <th>Created By</th>
                                    <th>Date Time</th>
                                    <th>Image</th>
                                </tr>
                            </thead>

                            <tbody>

                                {Array.isArray(tableData) && tableData.length > 0 ? (
                                    tableData.map((object, i) => (
                                        object && (   // check group is not null/undefined
                                            <tr key={object.plantId} className="table-row-hover">
                                                <td>
                                                    <div className="d-flex justify-content-center align-items-center">
                                                        <Button variant="outline-warning" size="sm" className="me-2"
                                                            onClick={() => navigate("/WebApplication/dashboard/plantMaster/addNewPlant",
                                                                { state: { object } })
                                                            }>
                                                            ✏
                                                        </Button>
                                                        <Button variant="outline-danger" size="sm" className="me-2" onClick={() => deleteData(object)}>
                                                            🗑
                                                        </Button>
                                                    </div>
                                                </td>
                                                <td>{sequenceNumber + i + 1}</td>
                                                <td data-label="Material">{object?.material}</td>
                                                <td data-label="Category">{object?.category?.category}</td>
                                                <td data-label="Description">{object?.description}</td>
                                                <td data-label="Created by">{object.createdBy}</td>
                                                <td data-label="Date Time">{object.dateTimeModified}</td>
                                                <td data-label="Image">
                                                    {object.image ? (
                                                        <a href={object.image} target="_blank" rel="noopener noreferrer">
                                                            View Image
                                                        </a>
                                                    ) : (
                                                        "No Image"
                                                    )}
                                                </td>
                                                <td style={{ display: "none" }}>{object.image}</td>
                                            </tr>
                                        )
                                    ))
                                ) : (
                                    <tr>
                                        <td colSpan="11" className="text-center">
                                            No Data Available
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </Table>
                    )}
                        </div>

                        {/* RIGHT SIDE ACTION PANEL */}
                        <div
                            style={{
                                width: "50px",
                                background: "linear-gradient(360deg, #0f6b5b, #0b4f43)",
                                color: "white",
                                borderLeft: "2px solid #e5e7eb",
                                display: "flex",
                                flexDirection: "column",
                                alignItems: "center",
                                paddingTop: "10px",
                                gap: "10px"
                            }}
                        >
                            <OverlayTrigger
                                placement="bottom"
                                overlay={<Tooltip id="download-tooltip">Add</Tooltip>}
                            >
                                <Button
                                    size="sm"
                                    className="btn btn-light shadow-sm"
                                    onClick={() =>
                                        navigate("/WebApplication/dashboard/roleMaster/addNewRole", { state: { formData } })
                                    }
                                >
                                    <Plus size={20} />
                                </Button>
                            </OverlayTrigger>


                            <OverlayTrigger
                                placement="bottom"
                                overlay={<Tooltip id="download-tooltip">Download Template</Tooltip>}
                            >
                                <Button
                                    size="sm"
                                    className="btn btn-light shadow-sm"
                                    onClick={() => downloadTemplate()}
                                >
                                    <Download size={20} />
                                </Button>
                            </OverlayTrigger>


                            <OverlayTrigger
                                placement="bottom"
                                overlay={<Tooltip id="download-tooltip">Upload Template</Tooltip>}
                            >
                                <Button
                                    size="sm"
                                    className="btn btn-light shadow-sm"
                                    onClick={() => showUploadModal()}
                                >
                                    <Upload size={20} />
                                </Button>
                            </OverlayTrigger>

                            {/* Future Buttons */}
                            {/* Download Template */}
                            {/* Upload Template */}

                        </div>

                    </div>
                </div>
            </div>


            <div className="row mt-2 mt-auto m-1"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>
                {/* <div className="col-md-6 d-flex align-items-center">
                    <div className="m-2">
                        <Button
                            size="lr"
                            className="btn-woco btn btn-light btn-sm 
                            d-flex align-items-center 
                            fw-semibold shadow-sm"

                            // className="me-2 btn-sm d-flex align-items-center fw-semibold shadow-sm btn-woco"
                            onClick={() =>
                                navigate("/WebApplication/dashboard/plantMaster/addNewPlant", { state: { formData } })
                            }
                        >
                            <Plus className="me-1" />
                            <span className="d-lg-inline">Add Plant</span>
                        </Button>
                    </div>
                </div> */}

                <div className="col-md-6 col-md-12 align-items-center radius-2">
                    <div className="m-2">
                        <Pager
                            currentPage={currentPage}
                            totalPages={totalPages}
                            onPageChange={setCurrentPage}
                            pageSize={pageSize}
                            onPageSizeChange={setPageSize}
                        />
                    </div>

                </div>
            </div>

        </div >
    );
};

export default StoreMaterialMaster;
