// CreateNewProject.js
import React, { useEffect, useState, useContext } from "react";
import axios from "axios";
import { Table, Button, Modal, Form } from "react-bootstrap";
import { Link } from "react-router-dom";
import { useNavigate, useLocation } from "react-router-dom";
import {
  HouseDoorFill,
  ListCheck,
  Calendar3,
  BarChart,
  People,
  Gear,
  QuestionCircle,
  BoxArrowRight,
  PersonCircle,
  Search,
  ArrowLeft,
  Check2Square,
  Eye,
  X
} from "react-bootstrap-icons";
import { Kanban, ClipboardCheck, Folder2Open } from "react-bootstrap-icons";
import "bootstrap/dist/css/bootstrap.min.css";
import "../css/Table.css"
import SearchInputFields from "../components/SearchInputFields"
import Pager from "../components/Pager";
import { useOutletContext } from "react-router-dom";
import TrainingDetailCard from '../components/TrainingDetailCard'
import { usePermissionStore } from "../auth/Permission";
import { RxCross2 } from "react-icons/rx";
import { TrainingContext } from "./TrainingContext";
import api from "../api/axiosInstance";
const BASE_URL = process.env.REACT_APP_BASE_URL;


const AllTrainingModel = () => {
  const context = useContext(TrainingContext);
  // 🔒 SAFETY CHECK (VERY IMPORTANT)
  if (!context) {
    throw new Error(
      "TrainingModelStep1 must be used inside TrainingContext.Provider"
    );
  }
  const { trainingDetails, setTrainingDetails } = context;
  const userDetails = usePermissionStore((state) => state.userDetails);
  // simple permission checker
  // const hasPermission = (permissionName) => permissions.includes(permissionName);
  const location = useLocation();
  const [trainingDetailsList, setTrainingDetailsList] = useState([]);
  // const [trainingDetails, setTrainingDetails] = useState({
  //   projectId: "",
  //   projectName: "",
  //   customerName: "",
  //   projectManger: "",
  //   startDate: "",
  //   endDate: "",
  //   createdBy: userDetails?.firstName
  //   // createdBy: "Deepak"
  // });
  const [error, setError] = useState("");
  const [currentPage, setCurrentPage] = useState(0);
  const [totalPages, setTotalPages] = useState(0);// dynamic in real apps
  const pageSize = 25;
  const sequenceNumber = pageSize * currentPage;
  const { setAlert } = useOutletContext();
  const navigate = useNavigate();
  const [projectManagerTypes, setProjectManagerType] = useState([]);
  const [customerTypes, setCustomerType] = useState([]);
  const [trainingName, setTrainingName] = useState("");

  const handleChange = (e) => {
    const { name, value } = e.target;
    setTrainingDetails((prev) => ({
      ...prev,      // keep all existing keys
      [name]: value // update only the changed field
    }));
  };

  // Handle form change
  const loadTrainingModelData = async () => {
    try {

      const formData = {
        trainingName: trainingName
      }
      // const response = await axios.post(
      //   BASE_URL + "/WebApplication/ExamTraining/getAllTrainingModel",
      //   formData,
      //   { withCredentials: true, } // 🚨 This ensures browser stores cookie 
      // );
      const response = await api.post(
        "/WebApplication/ExamTraining/getAllTrainingModel",
        formData
      );
      console.log("Data Load Sucessfully:", response);
      setTrainingDetailsList(response.data);
    } catch (error) {
      console.log(error);
    }
  };


  useEffect(() => {
    loadTrainingModelData();
  }, []); // empty deps → runs once


  // Handle form change
  const loadCustomerListData = async () => {
    const response = await axios.get(
      BASE_URL + "/WebApplication/ExamTraining/getAllCustomerInList",
      { withCredentials: true, } // 🚨 This ensures browser stores cookie 
    );
    setCustomerType(response.data);
  };


  const loadUserListData = async () => {
    const response = await axios.get(
      BASE_URL + "/WebApplication/ExamTraining/getAllUserInList",
      { withCredentials: true, } // 🚨 This ensures browser stores cookie 
    );
    setProjectManagerType(response.data);
  };

  // useEffect(() => {
  //   loadCustomerListData();
  //   loadUserListData();
  // }, []);


  return (
    <div className="card shadow-lg rounded-0 border-0 bg-light" style={{ width: "100%", height: "98vh", overflowX: "hidden", overflowY: "scroll" }}>
      {/* Header */}
      <div className="container-fluid rounded-top bg-gradient bg-dark text-white py-2 position-relative">
        {/* Title */}
        <h4 className="text-end fw-bold mb-0"><Check2Square size={30} viewBox="0 1 16 16" className="me-2 text-white" />
          All Training Models</h4>
        {/* Go Back button floated left
        <div className="position-absolute top-50 start-0 translate-middle-y ms-3" style={{ zIndex: 10 }}>
          <Button
            size="lr"
            className="btn btn-light btn-sm d-flex align-items-center fw-semibold shadow-sm"
            onClick={() =>
              navigate("/WebApplication/dashboard/kanban", { state: { trainingDetailsList } })
            }
          >
            <ArrowLeft className="me-1" />
            <span className="d-none d-lg-inline">Show trainingDetailsList Kanban Sheet</span>
          </Button>
        </div> */}
      </div>

      <div className="mt-3">
        <div className="row p-1 mb-3">
          <div className="col-md-2">
            <Button variant="outline-warning" className="w-100" onClick={loadTrainingModelData}>
              <Search className="me-1" /> Search
            </Button>
          </div>
          {/* <div className="col-md-4">
            <SearchInputFields type="date" name="startDate" onChange={handleChange} value={trainingDetails?.startDate} />
          </div>
          <div className="col-md-4">
            <SearchInputFields type="date" name="endDate" onChange={handleChange} value={trainingDetails?.endDate} />
          </div> 
          */}
          <div className="col-md-9">
            <SearchInputFields type="text" placeholder="Training Name" name="trainingName" onChange={(e)=>setTrainingName(e.target.value)} value={trainingName} />
          </div>

          {/* <div className="col-md-4">
            <SearchInputFields type="select" options={customerTypes} name="customerName" onChange={handleChange} value={trainingDetails?.customerName} />
          </div>
          <div className="col-md-4">
            <SearchInputFields type="select" options={projectManagerTypes} name="projectManager" onChange={handleChange} value={trainingDetails?.projectManager} />
          </div> */}

          <div className="col-md-1 text-center">
            <Button
              type="button"
              size="sm"
              // onClick={emptybarcode}
              style={{ width: "50px", height: "40px", flexShrink: 0 }}
              className="btn bg-secondary btn-sm"
              title="Clear Barcode"
            >
              <RxCross2 size={25} />
            </Button>
          </div>
        </div>


        <div className="container">
          <div className="row">
            {Array.isArray(trainingDetailsList) && trainingDetailsList.length > 0 ? (trainingDetailsList.map((trainingModel, index) => (
              <div className="col-md-3 mb-4" key={index}>
                <TrainingDetailCard trainingModel={trainingModel} location={location} formData={trainingDetails} userDetails={userDetails} loadTrainingModelData={loadTrainingModelData}></TrainingDetailCard>
              </div>
            ))) : (
              <div className="text-center bg-white">
                No Training Model Exist.....
              </div>
            )
            }
          </div>
        </div>
      </div>
    </div >

  );
};

export default AllTrainingModel;
