// DismissableAlert.js
import React from "react";
import { Alert } from "react-bootstrap"; // or use your own alert HTML

function DismissableAlert({ alert, setDismissAlertNull }) {
  if (!alert) return null;

  return (
    <div 
      className="position-fixed top-0 end-0 p-3" 
      style={{ zIndex: 2000 }}   // 👈 make it float above everything
    >
      <Alert 
        variant={alert.type || "info"} 
        dismissible 
        onClose={setDismissAlertNull}
        className="shadow-lg mb-2"
      >
        {alert.message}
      </Alert>
    </div>
  );
}

export default DismissableAlert;
